// Case study pages (results/<slug>/index.html, generated by scripts/build-cases.mjs).
import { initSite, gsap, ScrollTrigger, reduceMotion, toast } from '../../ds/site.js';
import { CASES } from '../../content/cases.js';
import { $, $$, trackHeaderOffset, revealHeadings, scrollSpy, tocJump, magnetic } from '../results/shared.js';
import { mountCaseHero, mountTheatre } from './scene-case.js';
import { cardFX, tiltGlare } from '../results/cardfx.js';
import { IND } from '../results/scene-sculpture.js';
import { initTone, initVMarquee, scrambleOnEnter } from '../industry/r2.js';
import '../results/results.css';
import '../results/fx.css';
import './case.css';
import './r2.css';

initSite();
trackHeaderOffset();
revealHeadings();

const slug = location.pathname.split('/').filter(Boolean).pop();
const data = CASES.find((c) => c.slug === slug);

// ---------------------------------------------------------------------------
// Cinematic hero: the camera drops from a plan view into the case's own before/after skyline (WebGL),
// the case index scrambles in, HUD lines draw. Then: tone backdrop, velocity marquee.
// ---------------------------------------------------------------------------
const photo = $('.cs-hero__photo');
const series = data?.results.chart?.series.map((s) => s.values);
mountCaseHero(photo, { series, color: photo?.dataset.color });
initTone();
initVMarquee();
const heroEl = $('.cs-hero');
const hx = $('[data-hud-x]');
const hy = $('[data-hud-y]');
heroEl?.addEventListener('pointermove', (e) => {
  const f = (v) => `${v >= 0 ? '+' : '−'}${Math.abs(v).toFixed(3)}`;
  hx.textContent = f((e.clientX / innerWidth) * 2 - 1);
  hy.textContent = f(-((e.clientY / innerHeight) * 2 - 1));
});
if (!reduceMotion) {
  const idx = $('[data-intro-scramble]');
  if (idx) gsap.from(idx, { duration: 1.6, delay: 0.2, scrambleText: { text: idx.textContent, chars: '0123456789CASE', speed: 0.5 } });
  gsap.from('.cs-hero__index-line', { scaleX: 0, transformOrigin: '0 50%', duration: 1.6, ease: 'expo.out', delay: 0.4 });
  gsap.from('.cs-hero .hud > *', { opacity: 0, duration: 1.2, stagger: 0.08, delay: 0.6, ease: 'power2.out' });
  gsap.from('.cs-hero__facts > div', { y: 16, opacity: 0, duration: 0.9, stagger: 0.07, delay: 0.9, ease: 'expo.out', clearProps: 'transform,opacity' });
  gsap.to('.cs-hero__row', { yPercent: -10, opacity: 0.3, ease: 'none', scrollTrigger: { trigger: heroEl, start: 'top top', end: 'bottom top', scrub: true } });
}

// ---------------------------------------------------------------------------
// Results theatre: scroll morphs the 3D bars from the "before" series into the "after" series (pinned on desktop)
// ---------------------------------------------------------------------------
const th = $('[data-theatre]');
if (th) {
  const before = JSON.parse(th.dataset.before);
  const after = JSON.parse(th.dataset.after);
  const unit = th.dataset.unit || '';
  const vals = $$('[data-th-v]', th);
  const bar = $('[data-th-bar]', th);
  const bName = $('[data-th-before]', th);
  const aName = $('[data-th-after]', th);
  let api = null;
  let p = 0;
  const set = (v) => {
    p = v;
    vals.forEach((el, i) => (el.textContent = `${Math.round(before[i] + (after[i] - before[i]) * v)}${unit}`));
    bar.style.transform = `scaleX(${v.toFixed(3)})`;
    bName.classList.toggle('is-on', v < 0.5);
    aName.classList.toggle('is-on', v >= 0.5);
    api?.setProgress(v);
  };
  mountTheatre($('[data-theatre-3d]', th), { series: [before, after], color: photo?.dataset.color }).then((a) => {
    api = a;
    if (a) th.classList.add('is-3d');
    a?.setProgress(p);
  });
  if (reduceMotion) set(1);
  else {
    set(0);
    const mmT = gsap.matchMedia();
    mmT.add('(min-width: 901px)', () => {
      const st = ScrollTrigger.create({ trigger: th, start: 'center center', end: '+=110%', pin: true, pinSpacing: true, anticipatePin: 1, scrub: true, onUpdate: (self) => set(self.progress) });
      return () => st.kill();
    });
    mmT.add('(max-width: 900px)', () => {
      const st = ScrollTrigger.create({ trigger: th, start: 'top 75%', end: 'bottom 35%', scrub: true, onUpdate: (self) => set(self.progress) });
      return () => st.kill();
    });
  }
}

// Giant metric values scramble in (placeholders stay placeholders; numeric ones use the DS counter)
scrambleOnEnter('.metric__before:not(:has([data-count])), .metric__after:not(:has([data-count]))', { chars: '0123456789$%XY[]', duration: 1.6 });

// Next / previous cards: WebGL photo + tilt glare
cardFX($$('.cs-nav__thumb'), {
  colorOf: (el) => IND[CASES.find((c) => el.closest('a')?.getAttribute('href') === `/results/${c.slug}/`)?.industry] || '#0792c2',
});
$$('.cs-nav__card').forEach((a) => {
  a.dataset.fxHost = '';
  tiltGlare(a, { max: 4 });
});

// ---------------------------------------------------------------------------
// Chapter HUD: big chapter number + per-chapter progress bars (fixed, desktop)
// ---------------------------------------------------------------------------
const chapter = $('[data-chapter]');
if (chapter) {
  const nEl = $('[data-chapter-n]', chapter);
  const lEl = $('[data-chapter-label]', chapter);
  const links = $$('[data-spy]');
  ScrollTrigger.create({ trigger: '.cs-body', start: 'top 60%', end: 'bottom 40%', toggleClass: { targets: chapter, className: 'is-on' } });
  $$('[data-chapter-bar]', chapter).forEach((b) => {
    const sec = document.getElementById(b.dataset.chapterBar);
    if (!sec) return;
    const fill = b.firstElementChild;
    ScrollTrigger.create({
      trigger: sec,
      start: 'top 50%',
      end: 'bottom 50%',
      onUpdate: (self) => (fill.style.transform = `scaleX(${self.progress.toFixed(3)})`),
      onToggle: (self) => {
        b.classList.toggle('is-active', self.isActive);
        if (!self.isActive) return;
        const link = links.find((l) => l.dataset.spy === sec.id);
        const [n, ...rest] = (link?.textContent || '').trim().split(/\s+/);
        lEl.textContent = rest.join(' ');
        if (reduceMotion) nEl.textContent = n;
        else gsap.to(nEl, { duration: 0.6, scrambleText: { text: n, chars: '0123456789', speed: 0.8 } });
      },
    });
  });
}

// ---------------------------------------------------------------------------
// On this page: scroll-spy, stage mini-map, mobile dropdown
// ---------------------------------------------------------------------------
const toc = $('.cs-toc');
const toggle = $('.cs-toc__toggle');
const current = $('[data-toc-current]');
const setOpen = (open) => {
  toc.classList.toggle('is-open', open);
  toggle.setAttribute('aria-expanded', String(open));
};
toggle.addEventListener('click', () => setOpen(!toc.classList.contains('is-open')));
tocJump(toc, () => setOpen(false));
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && toc.classList.contains('is-open')) {
    setOpen(false);
    toggle.focus();
  }
});

scrollSpy($$('[data-spy]'), (id) => {
  const link = $(`[data-spy="${id}"]`);
  if (link) current.textContent = link.textContent.replace(/\s+/g, ' ').trim();
});
const stageLinks = $$('.is-used [data-spy-sub]');
scrollSpy(stageLinks, (id) => $$('.stage').forEach((s) => s.classList.toggle('is-current', s.id === id && !s.classList.contains('stage--off'))), { line: 0.5 });

// ---------------------------------------------------------------------------
// "How we measured": popover on desktop, bottom sheet on mobile
// ---------------------------------------------------------------------------
let openPop = null;
const closePop = (focusBtn) => {
  if (!openPop) return;
  const { btn, pop } = openPop;
  pop.hidden = true;
  btn.setAttribute('aria-expanded', 'false');
  if (focusBtn) btn.focus();
  openPop = null;
};
$$('.hwm-btn').forEach((btn) => {
  const pop = document.getElementById(btn.getAttribute('aria-controls'));
  btn.addEventListener('click', (e) => {
    e.stopPropagation();
    const wasOpen = openPop?.btn === btn;
    closePop();
    if (wasOpen) return;
    pop.hidden = false;
    btn.setAttribute('aria-expanded', 'true');
    openPop = { btn, pop };
    $('.hwm__close', pop).focus({ preventScroll: true });
    if (!reduceMotion) gsap.fromTo(pop, { opacity: 0, y: 8 }, { opacity: 1, y: 0, duration: 0.35, ease: 'expo.out' });
  });
  $('.hwm__close', pop).addEventListener('click', () => closePop(true));
  pop.addEventListener('click', (e) => e.stopPropagation());
});
document.addEventListener('click', () => closePop());
document.addEventListener('keydown', (e) => e.key === 'Escape' && closePop(true));

// ---------------------------------------------------------------------------
// Share
// ---------------------------------------------------------------------------
const url = location.origin + location.pathname;
$$('[data-share]').forEach((a) => (a.href += encodeURIComponent(url)));
$('[data-copy-link]')?.addEventListener('click', async () => {
  try {
    await navigator.clipboard.writeText(url);
    toast({ title: 'Link copied', message: 'The case study link is on your clipboard.', type: 'success', duration: 3000 });
  } catch {
    toast({ title: 'Copy failed', message: url, type: 'error' });
  }
});

// ---------------------------------------------------------------------------
// Motion: scroll-scrubbed chart, stage choreography, magnetic CTAs
// ---------------------------------------------------------------------------
magnetic($$('.cs-cta .btn'));
const mm = gsap.matchMedia();
mm.add('(prefers-reduced-motion: no-preference)', () => {
  const chart = $('[data-chart]');
  if (chart) {
    const funnel = chart.classList.contains('chart--funnel');
    const tl = gsap.timeline({ scrollTrigger: { trigger: chart, start: 'top 85%', end: 'center 45%', scrub: 0.6 } });
    tl.from($$('.chart__bar', chart), {
      ...(funnel ? { scaleX: 0, transformOrigin: '0% 50%' } : { scaleY: 0, transformOrigin: '50% 100%' }),
      ease: 'power2.out',
      stagger: { each: 0.04, from: 'start' },
    });
    const values = $$('.chart__value', chart);
    if (values.length) tl.from(values, { opacity: 0, x: -6, stagger: 0.04 }, '<0.3');
  }
  // metrics: the "after" value slides in from the "before"
  $$('.metric').forEach((m) =>
    gsap.from($$('.metric__after, .metric__arrow', m), { x: -24, opacity: 0, duration: 0.9, ease: 'expo.out', stagger: 0.08, scrollTrigger: { trigger: m, start: 'top 85%' } }),
  );
  // unused stages fade to their dimmed state as the approach list passes
  if ($$('.stage--off').length) gsap.from('.stage--off', { opacity: 0, y: 16, duration: 0.6, stagger: 0.05, ease: 'power2.out', scrollTrigger: { trigger: '.stages', start: 'top 80%' } });
  gsap.from('.cs-nav__card', { y: 30, opacity: 0, duration: 0.8, stagger: 0.1, ease: 'expo.out', scrollTrigger: { trigger: '.cs-nav', start: 'top 90%' }, clearProps: 'transform,opacity' });
});

addEventListener('load', () => ScrollTrigger.refresh());
